PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('employee','manager','accountant')), email TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gl_accounts (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, gl_account_id TEXT NOT NULL REFERENCES gl_accounts(id));
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, name TEXT NOT NULL, category_id TEXT REFERENCES categories(id), effective_from TEXT NOT NULL, effective_to TEXT, receipt_threshold_cents INTEGER NOT NULL CHECK(receipt_threshold_cents >= 0), limit_cents INTEGER CHECK(limit_cents >= 0), mileage_rate_cents REAL CHECK(mileage_rate_cents > 0), allowance_cents INTEGER CHECK(allowance_cents > 0));
CREATE TABLE IF NOT EXISTS card_transactions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), merchant TEXT NOT NULL, date TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents > 0), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), last_four TEXT NOT NULL CHECK(length(last_four)=4));
CREATE TABLE IF NOT EXISTS receipts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), filename TEXT NOT NULL, mime_type TEXT NOT NULL, synthetic INTEGER NOT NULL DEFAULT 1 CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), job_id TEXT NOT NULL REFERENCES jobs(id), category_id TEXT NOT NULL REFERENCES categories(id), merchant TEXT NOT NULL CHECK(length(merchant)>0), description TEXT NOT NULL DEFAULT '', date TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents > 0 AND typeof(amount_cents)='integer'), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','returned','accounting_ready','exported')), receipt_id TEXT REFERENCES receipts(id), card_transaction_id TEXT UNIQUE REFERENCES card_transactions(id), report_id TEXT REFERENCES reports(id), miles REAL CHECK(miles > 0), mileage_rate_cents REAL CHECK(mileage_rate_cents > 0), payment_source TEXT NOT NULL DEFAULT 'employee' CHECK(payment_source IN ('employee','company_card')), exception_note TEXT NOT NULL DEFAULT '', missing_receipt_note TEXT NOT NULL DEFAULT '', approved_reimbursement_cents INTEGER CHECK(approved_reimbursement_cents>=0 AND approved_reimbursement_cents<=amount_cents), personal_cents INTEGER NOT NULL DEFAULT 0 CHECK(personal_cents>=0 AND personal_cents<=amount_cents), recovery_amount_cents INTEGER NOT NULL DEFAULT 0 CHECK(recovery_amount_cents>=0 AND recovery_amount_cents<=personal_cents), map_attached INTEGER NOT NULL DEFAULT 0 CHECK(map_attached IN (0,1)), missing_receipt INTEGER NOT NULL DEFAULT 0 CHECK(missing_receipt IN (0,1)), trip_purpose TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', day_fraction REAL NOT NULL DEFAULT 1 CHECK(day_fraction IN (0.5,1)), eligible INTEGER NOT NULL DEFAULT 0 CHECK(eligible IN (0,1)), rejection_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, expense_id TEXT NOT NULL REFERENCES expenses(id), user_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(id), expense_id TEXT REFERENCES expenses(id), action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS expense_status_idx ON expenses(status, date);
CREATE INDEX IF NOT EXISTS expense_user_idx ON expenses(user_id, date);
CREATE INDEX IF NOT EXISTS approval_expense_idx ON approvals(expense_id);
CREATE INDEX IF NOT EXISTS policy_effective_idx ON policies(category_id, effective_from, effective_to);
INSERT OR IGNORE INTO migrations(version) VALUES(1);
